import numpy as np
L=open('raw.xyz').read().split('\n')[2:]
s=[];X=[]
for l in L:
    if l.strip():
        p=l.split(); s.append(p[0]); X.append([float(x) for x in p[1:4]])
X=np.array(X)
import itertools
for i,j in itertools.combinations(range(len(s)),2):
    d=np.linalg.norm(X[i]-X[j])
    if d<1.9 and not (d<1.65): print(i,s[i],j,s[j],round(d,2))
"
